/* Lesson 65 starter (optional): the PIO state machine is set up for you.
 * Your job is the DMA part, marked TODO(learner). Until then the LEDs stay off. */
#include <stdio.h>

#include "pico/stdlib.h"
#include "hardware/dma.h"
#include "hardware/pio.h"
#include "pattern.pio.h"   /* generated by pioasm from pattern.pio */

#define PATTERN_PIO        pio0
#define PATTERN_SM         0u
#define PATTERN_BASE_PIN   10u   /* GP10 .. GP13 drive four LEDs */
#define PATTERN_PIN_COUNT  4u
#define PATTERN_CLKDIV_INT 60000u

/* Same program as the solution, from RP2040 datasheet section 3.4 (Table 366). */
static const uint16_t hand_decoded_words[] = {
    0x80A0,    /* pull block */
    0x7F04,    /* out pins, 4 [31] */
};

#define HAND_WORD_COUNT (sizeof hand_decoded_words / sizeof hand_decoded_words[0])

static const uint32_t steps[] = { 0x1, 0x2, 0x4, 0x8, 0x4, 0x2 };
#define STEP_COUNT (sizeof steps / sizeof steps[0])

int main(void) {
    stdio_init_all();

    /* pioasm generated pattern_program from pattern.pio. Compare its words with the
     * ones decoded by hand from the datasheet: they must be identical. */
    bool words_match = pattern_program.length == HAND_WORD_COUNT;
    for (uint i = 0; words_match && i < HAND_WORD_COUNT; i++) {
        words_match = pattern_program.instructions[i] == hand_decoded_words[i];
    }
    printf("PIO WORDS %s\n", words_match ? "MATCH" : "DIFFER");


    uint offset = pio_add_program(PATTERN_PIO, &pattern_program);
    for (uint i = 0; i < PATTERN_PIN_COUNT; i++) {
        pio_gpio_init(PATTERN_PIO, PATTERN_BASE_PIN + i);
    }
    pio_sm_set_consecutive_pindirs(PATTERN_PIO, PATTERN_SM, PATTERN_BASE_PIN, PATTERN_PIN_COUNT, true);

    pio_sm_config c = pio_get_default_sm_config();
    sm_config_set_wrap(&c, offset, offset + pattern_program.length - 1);
    sm_config_set_out_pins(&c, PATTERN_BASE_PIN, PATTERN_PIN_COUNT);
    sm_config_set_out_shift(&c, true, false, 32);
    sm_config_set_clkdiv_int_frac(&c, PATTERN_CLKDIV_INT, 0);
    pio_sm_init(PATTERN_PIO, PATTERN_SM, offset, &c);

    /* TODO(learner): feed the PIO TX FIFO with DMA.
     *  1. int ch = dma_claim_unused_channel(true);
     *  2. dma_channel_config dc = dma_channel_get_default_config(ch);
     *  3. Set the transfer size to 32 bits, read increment on, write increment off.
     *  4. channel_config_set_dreq(&dc, pio_get_dreq(PATTERN_PIO, PATTERN_SM, true));
     *     This is the pacing: the DMA waits for the FIFO's data request.
     *  5. dma_channel_configure(ch, &dc, &PATTERN_PIO->txf[PATTERN_SM], steps, STEP_COUNT, false);
     *  6. pio_sm_set_enabled(PATTERN_PIO, PATTERN_SM, true); then start the DMA and
     *     restart it in a loop when dma_channel_wait_for_finish_blocking() returns.
     *  Compare the solution's main.c when you are done. */

    printf("PIO ready, DMA TODO\n");
    while (true) {
        sleep_ms(1000);
    }
}
